def gen(rng):
    def fmt(a, m):
        return str(len(a)) + '\n' + ' '.join(map(str, a)) + '\n' + str(m)
    tests = [fmt([5], 1), fmt([5], 2), fmt([7, 7], 2), fmt([1, 10**9], 2), fmt([3, 1, 2], 3), fmt([3, 1, 2], 4)]
    for n in (2, 3, 4, 6, 8, 10):
        for _ in range(3):
            a = [rng.randint(1, 20) for _ in range(n)]
            tests.append(fmt(a, rng.randint(1, n + 1)))
    for _ in range(4):
        n = rng.randint(5, 12)
        a = [rng.randint(1, 10**9) for _ in range(n)]
        tests.append(fmt(a, rng.randint(1, n)))
    N = 10**5
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)], 50000))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)], N))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)], N - 1))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)], 2))
    tests.append(fmt([rng.randint(1, 1000) for _ in range(N)], 777))
    return tests

